--
-- Table structure for table `producto_inventario`
--

DROP TABLE IF EXISTS `producto_inventario`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `producto_inventario` (
  `producto_inventario_id` int NOT NULL AUTO_INCREMENT,
  `codigo_barras` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `sucursal_id` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `inventario_id` int DEFAULT NULL,
  `existencias` int DEFAULT '0',
  `fecha_ultima_actualizacion` datetime DEFAULT CURRENT_TIMESTAMP,
  `lote` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `fecha_caducidad` date DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `uq_llave_activo` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin GENERATED ALWAYS AS (if((`is_active` = 1),concat_ws(_utf8mb4'||',`codigo_barras`,`sucursal_id`,`lote`,`fecha_caducidad`),NULL)) VIRTUAL,
  PRIMARY KEY (`producto_inventario_id`),
  UNIQUE KEY `uq_pi_barras_sucursal_lote_cad` (`uq_llave_activo`),
  UNIQUE KEY `uq_llave_activo` (`uq_llave_activo`),
  KEY `inventario_id` (`inventario_id`),
  KEY `producto_inventario_ibfk_3_idx` (`sucursal_id`),
  KEY `idx_codigo_barras` (`codigo_barras`),
  CONSTRAINT `producto_inventario_ibfk_1` FOREIGN KEY (`codigo_barras`) REFERENCES `producto` (`codigo_barras`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `producto_inventario_ibfk_2` FOREIGN KEY (`inventario_id`) REFERENCES `inventario` (`inventario_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `producto_inventario_ibfk_3` FOREIGN KEY (`sucursal_id`) REFERENCES `sucursal` (`sucursal_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12797 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
/*!40101 SET character_set_client = @saved_cs_client */;

